sp_widget.client_script:
api.controller=function($scope) {

    var c = this;

    c.openComplaint = function(complaintSysId, studentSysId) {

        var url =
            'https://ltm-hck-2876-0046.lab.service-now.com/now/nav/ui/classic/params/target/x_snc_campus_foo_1_food_complaint.do%3Fsys_id%3Df35e96fd806343107f4447e44ab1d51f%26sysparm_record_target%3Dx_snc_campus_foo_1_food_complaint%26sysparm_record_row%3D1%26sysparm_record_rows%3D1%26sysparm_record_list%3Dstudent%253D99dc4dab085703107f447d6c83c822aa%255Estate%253Dactive%255EORDERBYuse_case'

        window.open(url, '_blank');

    };

}

sp_widget.css:
.complaint-container {
    width: 100%;
    padding: 20px;
    box-sizing: border-box;
}

.complaint-container h2 {
    margin: 0 0 20px 0;
    font-size: 24px;
    font-weight: 600;
}

.table-wrapper {
    width: 100%;
    overflow-x: auto;
    border: 1px solid #ddd;
    border-radius: 8px;
}

.complaint-table {
    width: 100%;
    min-width: 1800px;
    border-collapse: collapse;
    background: #fff;
}

.complaint-table th {
    background: #f4f6f8;
    color: #333;
    padding: 12px;
    text-align: left;
    font-weight: 600;
    border-bottom: 2px solid #ddd;
    white-space: nowrap;
}

.complaint-table td {
    padding: 12px;
    border-bottom: 1px solid #e5e5e5;
    color: #444;
    vertical-align: top;
}

.complaint-table tbody tr:hover {
    background: #f8f9fa;
}

.feedback-badge {
    display: inline-block;
    padding: 4px 8px;
    border-radius: 12px;
    font-size: 12px;
    font-weight: 600;
}

.feedback-badge.eligible {
    background: #dff5e3;
    color: #1b6b2a;
}

.feedback-badge.not-eligible {
    background: #f1f1f1;
    color: #666;
}

.state-badge {
    display: inline-block;
    padding: 5px 10px;
    border-radius: 12px;
    background: #e8f1ff;
    color: #245a9b;
    font-size: 12px;
    font-weight: 600;
}

.complaint-table td:nth-child(5),
.complaint-table td:nth-child(11) {
    min-width: 250px;
    max-width: 350px;
    white-space: normal;
    word-break: break-word;
}
.open-complaint-btn {
    padding: 8px 14px;
    border: none;
    border-radius: 5px;
    cursor: pointer;
    font-size: 13px;
    background: #1976d2;
    color: white;
}

.open-complaint-btn:hover {
    opacity: 0.85;
}

sp_widget.script:
(function() {

    data.complaints = [];

    var gr = new GlideRecord('x_snc_campus_foo_1_food_complaint');

    gr.addEncodedQuery('student=99dc4dab085703107f447d6c83c822aa^state=active');

    gr.query();

    while (gr.next()) {

        data.complaints.push({
			complaint_sys_id: gr.getUniqueValue(),
			student_sys_id: gr.getValue('student'),
            student: gr.getDisplayValue('student'),
            number: gr.getValue('number'),
            use_case: gr.getValue('use_case'),
            base_problem: gr.getDisplayValue('base_problem'),
            description: gr.getValue('description'),
            created_by: gr.getDisplayValue('sys_created_by'),
            feedback_eligible: gr.getValue('feedback_eligible'),
            meal_type: gr.getDisplayValue('meal_type'),
            mess_hall: gr.getDisplayValue('mess_hall'),
            problem_type: gr.getDisplayValue('problem_type'),
            resolution_notes: gr.getValue('resolution_notes'),
            opened_at: gr.getDisplayValue('opened_at'),
            priority: gr.getDisplayValue('priority'),
            resolved_at: gr.getDisplayValue('resolved_at'),
            state: gr.getDisplayValue('state'),
            feedback_id: gr.getDisplayValue('feedback_id')
        });

    }

})();
